<script setup>
import {computed} from 'vue'
import {useTelemetryStore} from '../stores/telemetry.js'
const telemetry=useTelemetryStore(),zones=computed(()=>telemetry.snapshot?.zones??[])
const box=computed(()=>{if(!zones.value.length)return '0 0 800 400';const xs=zones.value.map(z=>z.geometry.x),ys=zones.value.map(z=>z.geometry.y);return `${Math.min(...xs)-80} ${Math.min(...ys)-70} ${Math.max(250,Math.max(...xs)-Math.min(...xs)+180)} ${Math.max(180,Math.max(...ys)-Math.min(...ys)+140)}`})
const positions=computed(()=>telemetry.snapshot?.mode==='operational'?[]:(telemetry.snapshot?.readings??[]).filter(r=>r.metric==='position'&&r.simulation===true&&r.value&&typeof r.value==='object'&&!['unavailable','offline'].includes(r.quality)))
</script>
<template><div class="zone-schematic"><p class="stat-label">Fictional mine schematic · Not surveyed · {{positions.length?'Last-known backend simulated movement':'No verified positions inferred'}}</p><p v-if="!zones.length" class="empty-copy">No zone configuration available.</p><svg v-else :viewBox="box" role="img" aria-label="Fictional zone geometry; coordinates do not represent a surveyed mine"><g v-for="z in zones" :key="z.id"><rect :x="z.geometry.x-15" :y="z.geometry.y-15" width="30" height="30" rx="5" fill="#123c4a" stroke="#4bdbcb"/><text :x="z.geometry.x+23" :y="z.geometry.y-2" fill="#d1e4fe" font-size="12">{{z.name}}</text><text :x="z.geometry.x+23" :y="z.geometry.y+14" fill="#9cb6c6" font-size="9">Administrative depth {{z.depth}} m</text></g><g v-for="r in positions" :key="r.id"><circle :cx="r.value.x" :cy="r.value.y" r="5" fill="#ffb95f"/><text :x="r.value.x+8" :y="r.value.y+8" fill="#ffcf8c" font-size="8">{{r.workerId}} · SIMULATED</text></g></svg><p>Physical GNSS/UWB observations use their own coordinate systems and are never projected onto this diagram.</p></div></template>
<style scoped>.zone-schematic{background-color:#041727;background-image:linear-gradient(#1d354230 1px,transparent 1px),linear-gradient(90deg,#1d354230 1px,transparent 1px);background-size:28px 28px;border:1px solid #243e50;border-radius:9px;padding:18px;min-height:240px}.zone-schematic svg{display:block;width:100%;max-height:360px;min-height:220px}.zone-schematic>p:last-child{font-size:10px;color:#9cb2c1}</style>
